// Catalogue search over the global catalogue plus the workspace's own items.
// Empty text filters mean "any". only_in_stock limits the result to items that are in stock.
func (q *Queries) SearchCraftCatalog(ctx context.Context, arg SearchCraftCatalogParams) ([]SearchCraftCatalogRow, error) {
	rows, err := q.db.Query(ctx, searchCraftCatalog,
		arg.WorkspaceID,
		arg.Category,
		arg.Manufacturer,
		arg.Query,
		arg.OnlyInStock,
		arg.PageOffset,
		arg.PageLimit,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []SearchCraftCatalogRow{}
	for rows.Next() {
		var i SearchCraftCatalogRow
		if err := rows.Scan(
			&i.ID,
			&i.WorkspaceID,
			&i.CategoryID,
			&i.ManufacturerID,
			&i.Article,
			&i.Series,
			&i.Name,
			&i.ColorName,
			&i.ColorHex,
			&i.ColorSource,
			&i.Size,
			&i.Finish,
			&i.Unit,
			&i.PackSize,
			&i.Attrs,
			&i.Source,
			&i.SourceUrl,
			&i.ImageUrl,
			&i.ExternalID,
			&i.FetchedAt,
			&i.ManualOverride,
			&i.DeprecatedAt,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.PhotoColorHex,
			&i.PhotoColorUrl,
			&i.PhotoColorAt,
			&i.ShopColorHex,
			&i.CategorySlug,
			&i.CategoryName,
			&i.ManufacturerName,
			&i.StockQty,
			&i.InInventory,
			&i.StockAttrs,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

